package pre13mini;
import java.lang.reflect.*;import java.util.*;import pre13mini.annotation.Id;
public class Repository<T> {private final HashMap<String,T> data=new HashMap<>();private String idOf(T entity){for(Field f:entity.getClass().getDeclaredFields())if(f.isAnnotationPresent(Id.class)){try{f.setAccessible(true);return String.valueOf(f.get(entity));}catch(IllegalAccessException e){throw new IllegalStateException("Cannot read @Id field",e);}}throw new IllegalArgumentException("No field marked @Id in "+entity.getClass().getSimpleName());}public T save(T entity){data.put(idOf(entity),entity);return entity;}@SafeVarargs public final void saveAll(T...items){for(T item:items)save(item);}public T findById(String id){return data.get(id);}public ArrayList<T> findAll(){return new ArrayList<>(data.values());}public boolean delete(String id){return data.remove(id)!=null;}public int size(){return data.size();}public static <N extends Number> double average(N[] values){if(values.length==0)throw new IllegalArgumentException("Array cannot be empty");double sum=0;for(N n:values)sum+=n.doubleValue();return sum/values.length;}}
